code.java:
class Solution {
    public long flowerGame(int n,int m){
        long oddN=(n+1L)/2,evenN=n/2,oddM=(m+1L)/2,evenM=m/2;
        return oddN*evenM+evenN*oddM;
    }
}

code.kotlin:
class Solution {
    fun flowerGame(n:Int,m:Int):Long{
        val oddN=(n.toLong()+1)/2;
        val evenN=n.toLong()/2;
        val oddM=(m.toLong()+1)/2;
        val evenM=m.toLong()/2;
        return oddN*evenM+evenN*oddM
    }
}

